#pragma once
#include <windows.h>
#include <d3d12.h>
#include <d3dcompiler.h>
#include <wrl/client.h>
#include <array>
#include <cstring>
#include <string>
#include <stdexcept>

namespace gh2::temporal {
// Producer payload, not guest vertex layout. Both clip positions must have
// been generated by the correct current/previous title position programs.
struct MotionVertex {std::array<float,4> current,previous;float history_valid;};
static_assert(sizeof(MotionVertex)==36);
class MotionRaster {
    Microsoft::WRL::ComPtr<ID3D12RootSignature> root_;
    Microsoft::WRL::ComPtr<ID3D12PipelineState> pipeline_;
    static void Require(HRESULT hr){if(FAILED(hr))throw std::runtime_error("Motion raster D3D12 operation failed");}
public:
    void Initialize(ID3D12Device* device) {
        D3D12_DESCRIPTOR_RANGE range{D3D12_DESCRIPTOR_RANGE_TYPE_SRV,1,0,0,0};
        std::array<D3D12_ROOT_PARAMETER,2> parameters{};
        parameters[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;parameters[0].DescriptorTable={1,&range};
        parameters[1].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;parameters[1].Constants={0,0,4};
        D3D12_ROOT_SIGNATURE_DESC desc{};desc.NumParameters=2;desc.pParameters=parameters.data();desc.Flags=D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
        Microsoft::WRL::ComPtr<ID3DBlob> root_blob,error;
        Require(D3D12SerializeRootSignature(&desc,D3D_ROOT_SIGNATURE_VERSION_1,&root_blob,&error));
        Require(device->CreateRootSignature(0,root_blob->GetBufferPointer(),root_blob->GetBufferSize(),IID_PPV_ARGS(&root_)));
        const char* shader=R"(
Texture2D<float> sceneDepth : register(t0);
cbuffer Frame : register(b0) {float2 dimensions;float epsilon;float unused;};
struct In {float4 current:POSITION0;float4 previous:POSITION1;float valid:TEXCOORD0;};
struct Vertex {float4 position:SV_Position;float4 previous:TEXCOORD0;float valid:TEXCOORD1;};
Vertex vs_main(In input){Vertex result;result.position=input.current;result.previous=input.previous;result.valid=input.valid;return result;}
struct Output {float2 velocity:SV_Target0;uint valid:SV_Target1;};
Output ps_main(Vertex input) {
    // Respect current visibility. An occluded replay must not erase a vector
    // that was written by the visible foreground surface.
    float depth=sceneDepth.Load(int3(int2(input.position.xy),0));
    if(!isfinite(depth)||abs(input.position.z-depth)>epsilon)discard;
    Output result;result.velocity=0;result.valid=0;
    if(input.valid<0.99999||input.previous.w<=0.000001||!all(isfinite(input.previous)))return result;
    float2 previousPixel=(input.previous.xy/input.previous.w*float2(0.5,-0.5)+0.5)*dimensions;
    // D3D SV_Position is already in current pixel coordinates, including the
    // half-pixel center. Backward flow is what DLSS expects.
    result.velocity=previousPixel-input.position.xy;
    result.valid=all(isfinite(result.velocity));
    if(!result.valid)result.velocity=0;
    return result;
})";
        Microsoft::WRL::ComPtr<ID3DBlob> vs,ps;
        auto compile=[&](const char* entry,const char* profile,Microsoft::WRL::ComPtr<ID3DBlob>& blob){
            error.Reset();const auto hr=D3DCompile(shader,std::strlen(shader),"gh2_motion_raster",nullptr,nullptr,entry,profile,D3DCOMPILE_OPTIMIZATION_LEVEL3,0,&blob,&error);
            if(FAILED(hr))throw std::runtime_error(error?std::string(static_cast<const char*>(error->GetBufferPointer()),error->GetBufferSize()):"Motion shader compilation failed");};
        compile("vs_main","vs_5_1",vs);compile("ps_main","ps_5_1",ps);
        const std::array<D3D12_INPUT_ELEMENT_DESC,3> layout={{{"POSITION",0,DXGI_FORMAT_R32G32B32A32_FLOAT,0,0,D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA,0},
            {"POSITION",1,DXGI_FORMAT_R32G32B32A32_FLOAT,0,16,D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA,0},
            {"TEXCOORD",0,DXGI_FORMAT_R32_FLOAT,0,32,D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA,0}}};
        D3D12_GRAPHICS_PIPELINE_STATE_DESC p{};p.pRootSignature=root_.Get();p.VS={vs->GetBufferPointer(),vs->GetBufferSize()};p.PS={ps->GetBufferPointer(),ps->GetBufferSize()};
        p.InputLayout={layout.data(),UINT(layout.size())};p.PrimitiveTopologyType=D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;
        p.NumRenderTargets=2;p.RTVFormats[0]=DXGI_FORMAT_R16G16_FLOAT;p.RTVFormats[1]=DXGI_FORMAT_R8_UINT;p.SampleDesc.Count=1;p.SampleMask=UINT_MAX;
        p.RasterizerState.FillMode=D3D12_FILL_MODE_SOLID;p.RasterizerState.CullMode=D3D12_CULL_MODE_NONE;p.RasterizerState.DepthClipEnable=TRUE;
        p.DepthStencilState.DepthEnable=FALSE;p.DepthStencilState.StencilEnable=FALSE;
        for(auto& target:p.BlendState.RenderTarget)target.RenderTargetWriteMask=D3D12_COLOR_WRITE_ENABLE_ALL;
        Require(device->CreateGraphicsPipelineState(&p,IID_PPV_ARGS(&pipeline_)));
    }
    template<class Commands>
    bool Record(Commands* commands,ID3D12Resource* vertices,uint32_t count,
                ID3D12DescriptorHeap* depth_heap,D3D12_GPU_DESCRIPTOR_HANDLE depth_table,
                const std::array<D3D12_CPU_DESCRIPTOR_HANDLE,2>& targets,uint32_t width,uint32_t height,
                D3D12_RECT scissor,bool clip_history_verified,bool depth_visibility_verified) {
        if(!commands||!vertices||!depth_heap||!pipeline_||!targets[0].ptr||!targets[1].ptr||!width||!height||!count||count%3||
           !clip_history_verified||!depth_visibility_verified||scissor.left<0||scissor.top<0||
           scissor.right>LONG(width)||scissor.bottom>LONG(height)||scissor.right<=scissor.left||scissor.bottom<=scissor.top)return false;
        const auto desc=vertices->GetDesc();if(desc.Dimension!=D3D12_RESOURCE_DIMENSION_BUFFER||uint64_t(count)*sizeof(MotionVertex)>desc.Width)return false;
        commands->SetDescriptorHeaps(1,&depth_heap);commands->SetGraphicsRootSignature(root_.Get());commands->SetPipelineState(pipeline_.Get());
        commands->SetGraphicsRootDescriptorTable(0,depth_table);
        const std::array<float,4> constants={float(width),float(height),0.0001f,0};commands->SetGraphicsRoot32BitConstants(1,4,constants.data(),0);
        const D3D12_VIEWPORT viewport{0,0,float(width),float(height),0,1};commands->RSSetViewports(1,&viewport);commands->RSSetScissorRects(1,&scissor);
        commands->OMSetRenderTargets(2,targets.data(),FALSE,nullptr);commands->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
        const D3D12_VERTEX_BUFFER_VIEW view{vertices->GetGPUVirtualAddress(),count*uint32_t(sizeof(MotionVertex)),uint32_t(sizeof(MotionVertex))};commands->IASetVertexBuffers(0,1,&view);
        commands->DrawInstanced(count,1,0,0);return true;
    }
    template<class Commands>
    bool RecordUncertifiedDiagnostic(Commands* commands,ID3D12Resource* vertices,uint32_t count,
                ID3D12DescriptorHeap* depth_heap,D3D12_GPU_DESCRIPTOR_HANDLE depth_table,
                const std::array<D3D12_CPU_DESCRIPTOR_HANDLE,2>& targets,uint32_t width,uint32_t height,D3D12_RECT scissor) {
        // This output is a mathematical candidate, not certified object motion.
        // It must never satisfy DLSS Inputs::object_motion_valid or be consumed
        // as a production velocity texture without independent validation.
        return Record(commands,vertices,count,depth_heap,depth_table,targets,width,height,scissor,true,true);
    }
};
}
